from datetime import date, timedelta


class Library:
    def __init__(self, loan_days: int = 14, daily_fine: float = 0.5) -> None:
        self.loan_days = loan_days
        self.daily_fine = daily_fine
        self._books = set()
        self._borrowed = {}  # book_id -> (user, borrow_day)
        self._fines = {}     # user -> unpaid amount
        self._history = {}   # user -> list of book_ids in borrow order
        self._titles = {}    # book_id -> title

    def add_book(self, book_id: str, title: str = "") -> None:
        if book_id in self._books or book_id in self._borrowed:
            raise ValueError(f"book {book_id!r} already exists")
        self._books.add(book_id)
        self._titles[book_id] = title

    def title(self, book_id: str) -> str:
        if book_id not in self._books and book_id not in self._borrowed:
            raise ValueError(f"unknown book {book_id!r}")
        return self._titles.get(book_id, "")

    def borrow(self, user: str, book_id: str, day: date) -> None:
        if book_id not in self._books and book_id not in self._borrowed:
            raise ValueError(f"unknown book {book_id!r}")
        if book_id in self._borrowed:
            raise ValueError(f"book {book_id!r} is already borrowed")
        # Rule 4: a user with unpaid fines may hold at most one book at a time
        if self._fines.get(user, 0) > 0:
            held = sum(1 for (u, _d) in self._borrowed.values() if u == user)
            if held >= 1:
                raise ValueError(
                    f"user {user!r} has unpaid fines and already holds a book"
                )
        self._borrowed[book_id] = (user, day)
        self._history.setdefault(user, []).append(book_id)

    def return_book(self, user: str, book_id: str, day: date) -> float:
        if book_id not in self._borrowed:
            raise ValueError(f"book {book_id!r} is not currently borrowed")
        borrower, borrow_day = self._borrowed[book_id]
        if borrower != user:
            raise ValueError(
                f"book {book_id!r} was not borrowed by {user!r}"
            )
        del self._borrowed[book_id]

        due_day = borrow_day + timedelta(days=self.loan_days)
        if day <= due_day:
            return 0.0

        # Count weekdays strictly after due_day up to and including day.
        delay_days = 0
        cur = due_day + timedelta(days=1)
        while cur <= day:
            if cur.weekday() < 5:  # Mon..Fri
                delay_days += 1
            cur += timedelta(days=1)

        fine = delay_days * self.daily_fine
        if fine > 0:
            self._fines[user] = self._fines.get(user, 0.0) + fine
        return fine

    def unpaid_fines(self, user: str) -> float:
        return self._fines.get(user, 0.0)

    def pay(self, user: str) -> None:
        self._fines.pop(user, None)

    def available(self) -> list[str]:
        return sorted(b for b in self._books if b not in self._borrowed)

    def history(self, user: str) -> list[str]:
        return list(self._history.get(user, []))
```

